module fixed_point_subtractor (
    input [N-1:0] a, b,
    output [N-1:0] c
);
// Parameters
    parameter Q = 16;
    parameter N = 32;
// Internal wires and regs
    reg [N-1:0] res;
    reg [N-1:0] temp;
    reg [N-1:0] diff;
// Combinational logic for subtraction
    always @(*) begin
        if(a[N-1] == b[N-1]) begin
            // Same sign subtraction
            diff = a[N-1:0] - b[N-1:0];
            res = {diff[N-1:0]};
        end else begin
            // Different sign subtraction
            temp = a[N-1:0] + b[N-1:0];
            if(temp[N-1] == 1'b0 && a > b) begin
                res = temp[N-1:0];
                res[N-1] = 1'b1; // Positive sign
            end else begin
                res = temp[N-1:0];
                res[N-1] = 1'b0; // Negative sign
            end
        end

        // Handle special case for zero
        if(res == 0) begin
            res[N-1] = 0; // Set the sign bit to 0
        end
    end

    // Output the result
    assign c = res[N-1:0];
endmodule
